const updateGame = `-- name: UpdateGame :one
UPDATE games
SET name = $1, slug = $2, updated_at = now()
WHERE id = $3::uuid
RETURNING id::text, name, slug, active, created_at, updated_at
`

type UpdateGameParams struct {
	Name string
	Slug string
	ID   pgtype.UUID
}

type UpdateGameRow struct {
	ID        string
	Name      string
	Slug      string
	Active    bool
	CreatedAt pgtype.Timestamptz
	UpdatedAt pgtype.Timestamptz
}

func (q *Queries) UpdateGame(ctx context.Context, arg UpdateGameParams) (UpdateGameRow, error) {
	row := q.db.QueryRow(ctx, updateGame, arg.Name, arg.Slug, arg.ID)
	var i UpdateGameRow
	err := row.Scan(
		&i.ID,
		&i.Name,
		&i.Slug,
		&i.Active,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
